    // تحميل الحلقات للسيرفر المختار
    function loadEpisodesForServer(serverId) {
        const grid = document.getElementById('episodesGrid');
        grid.innerHTML = '';
        const episodes = serversData[serverId];

        episodes.forEach((episode) => {
            const btn = document.createElement('button');
            btn.className = 'ep-btn';
            btn.textContent = episode.name;
            btn.onclick = function() {
                loadEpisode(this, episode.url);
            };
            grid.appendChild(btn);
        });

        // تحميل أول حلقة تلقائياً
        const firstBtn = grid.querySelector('.ep-btn');
        if (firstBtn && serversData[serverId][0].url) {
            loadEpisode(firstBtn, serversData[serverId][0].url, false);
        }
    }

    // تبديل السيرفرات
    function switchServer(serverId) {
        currentServer = serverId;

        // تحديث أزرار السيرفر
        document.querySelectorAll('.server-btn').forEach(btn => {
            btn.classList.remove('active');
        });
        event.target.classList.add('active');

        // تحميل الحلقات الجديدة
        loadEpisodesForServer(serverId);
    }

    function loadEpisode(btn, url, showAd = true) {
        if (!url || url === '') {
            alert('هذه الحلقة لم تضيفها بعد');
            return;
        }

        currentServerUrl = url;
        updateFrameSource(currentServerUrl);

        if (showAd) {
            document.getElementById('adOverlay').style.display = 'flex';
        }

        document.querySelectorAll('.ep-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
    }

    function updateFrameSource(url) {
        let finalUrl = url;
        if (url.includes('drive.google.com')) {
            let fileId = "";
            if (url.includes('/file/d/')) {
                fileId = url.split('/file/d/')[1].split('/')[0];
            } else if (url.includes('id=')) {
                fileId = url.split('id=')[1].split('&')[0];
            }
            finalUrl = `https://drive.google.com/file/d/${fileId}/preview`;
        }
        document.getElementById('customPlayerFrame').src = finalUrl;
    }

    function closeAd() {
        document.getElementById('adOverlay').style.display = 'none';
    }

    window.onload = function() {
        // تحميل السيرفر الثاني افتراضياً
        loadEpisodesForServer('server2');
    };
