<script>
    let currentServerUrl = "";

    function filterChapter(chapterNumber, btn) {
        document.querySelectorAll('.chapter-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        document.querySelectorAll('.ep-btn').forEach(ep => {
            if(ep.getAttribute('data-chapter') == chapterNumber) {
                ep.style.display = 'block';
            } else {
                ep.style.display = 'none';
            }
        });
    }

    function loadEpisode(btn, url, showAd = true) {
        if (!url || url === '') return;

        currentServerUrl = url;
        updateFrameSource(currentServerUrl);

        if (showAd) {
            document.getElementById('adOverlay').style.display = 'flex';
        }

        document.querySelectorAll('.ep-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
    }

    function updateFrameSource(url) {
        let finalUrl = url;
        if (url.includes('drive.google.com')) {
            let fileId = "";
            if (url.includes('/file/d/')) {
                fileId = url.split('/file/d/')[1].split('/')[0];
            } else if (url.includes('id=')) {
                fileId = url.split('id=')[1].split('&')[0];
            }
            finalUrl = `https://drive.google.com/file/d/${fileId}/preview`;
        }
        document.getElementById('customPlayerFrame').src = finalUrl;
    }

    function closeAd() {
        document.getElementById('adOverlay').style.display = 'none';
    }

    window.onload = function() {
        filterChapter(1, document.querySelector('.chapter-btn'));

        const firstBtn = document.querySelector('.ep-btn');
        if (firstBtn) {
            const onclickAttr = firstBtn.getAttribute('onclick');
            const match = onclickAttr.match(/'([^']*)'/);
            if (match && match[1] !== 'رابط_1') {
                loadEpisode(firstBtn, match[1], false);
            }
        }
    };
</script>

