        position: relative;
        background: radial-gradient(ellipse at center, #111118 0%, #000000 100%);
        padding: 12px;
        aspect-ratio: 16/9;
    }

    .video-wrapper::after {
        content: '';
        position: absolute;
        bottom: 0;
        left: 12px;
        right: 12px;
        height: 1px;
        background: linear-gradient(90deg, transparent, var(--primary-color), transparent);
        opacity: 0.3;
    }

    .block-popout {
        position: absolute;
        top: 12px;
        right: 12px;
        width: 60px;
        height: 60px;
        z-index: 10;
        background: rgba(255, 255, 255, 0);
        cursor: default;
    }

    #customPlayerFrame {
        width: 100%;
        height: 100%;
        border-radius: 12px;
        border: 1px solid var(--border-subtle);
        display: block;
        background: #000;
    }

    /* === قسم السيرفر === */
    .server-selection {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 15px;
        padding: 16px 20px;
        background: linear-gradient(180deg, var(--bg-elevated) 0%, var(--bg-card) 100%);
        border-bottom: 1px solid var(--border-subtle);
    }

    .server-selection span {
        color: var(--text-muted);
        font-size: 13px;
        font-weight: 500;
        letter-spacing: 0.3px;
    }

    .server-btn {
        background: var(--bg-dark);
        color: var(--text-primary);
        border: 1px solid var(--border-subtle);
        padding: 9px 24px;
        border-radius: 10px;
        cursor: pointer;
        font-size: 13px;
        font-weight: 700;
        font-family: 'Tajawal', sans-serif;
        transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
        position: relative;
        overflow: hidden;
    }

    .server-btn::before {
        content: '';
        position: absolute;
        inset: 0;
        background: var(--accent-gradient);
        opacity: 0;
        transition: opacity 0.35s;
    }

    .server-btn span {
        position: relative;
        z-index: 1;
    }

    .server-btn:hover {
        border-color: var(--border-active);
        transform: translateY(-1px);
        box-shadow: 0 4px 20px var(--primary-glow);
    }

    .server-btn.active {
        background: var(--accent-gradient);
        border-color: transparent;
        color: white;
        box-shadow: 0 4px 25px var(--primary-glow), 0 0 0 1px rgba(231, 76, 60, 0.2);
    }

    /* === أزرار الفصول === */
    .chapters-nav {
        display: flex;
        gap: 8px;
        padding: 16px 20px 0;
        background: var(--bg-card);
        flex-wrap: wrap;
    }

    .chapter-btn {
        background: var(--bg-dark);
        color: var(--text-muted);
        border: 1px solid var(--border-subtle);
        padding: 9px 18px;
        border-radius: 10px;
        cursor: pointer;
        font-size: 12.5px;
        font-weight: 600;
        font-family: 'Tajawal', sans-serif;
        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        white-space: nowrap;
    }

    .chapter-btn:hover {
        color: var(--text-primary);
        border-color: rgba(255, 255, 255, 0.12);
        background: var(--bg-elevated);
        transform: translateY(-1px);
    }

    .chapter-btn.active {
        background: var(--accent-gradient);
        color: white;
        border-color: transparent;
        box-shadow: 0 3px 18px var(--primary-glow);
    }

    /* === قائمة الحلقات === */
    .episodes-list {
        background: var(--bg-card);
        padding: 20px;
    }

    .episodes-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(82px, 1fr));
        gap: 8px;
        max-height: 260px;
        overflow-y: auto;
        padding: 4px;
    }

    .ep-btn {
        background: var(--bg-dark);
        color: var(--text-muted);
        border: 1px solid var(--border-subtle);
