        border-radius: 12px;
        padding: 10px;
        border: 1px solid var(--border-subtle);
    }

    .close-ad-btn {
        background: var(--accent-gradient);
        color: white;
        border: none;
        padding: 13px 28px;
        border-radius: 12px;
        cursor: pointer;
        font-weight: 800;
        font-size: 14px;
        font-family: 'Tajawal', sans-serif;
        width: 100%;
        margin-top: 15px;
        transition: all 0.3s;
        letter-spacing: 0.3px;
    }

    .close-ad-btn:hover {
        transform: translateY(-2px);
        box-shadow: 0 8px 30px var(--primary-glow);
    }

    /* === زر العودة === */
    .back-btn-wrapper {
        margin: 30px 20px;
        text-align: center;
    }

    .back-btn-wrapper a {
        background: var(--accent-gradient);
        border-radius: 50px;
        color: white;
        display: inline-block;
        font-family: 'Tajawal', sans-serif;
        font-weight: 800;
        padding: 13px 32px;
        text-decoration: none;
        font-size: 14px;
        transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
        box-shadow: 0 4px 20px var(--primary-glow);
        letter-spacing: 0.3px;
    }

    .back-btn-wrapper a:hover {
        transform: translateY(-3px);
        box-shadow: 0 8px 35px rgba(231, 76, 60, 0.45);
    }

    /* === حركات عامة === */
    @keyframes subtlePulse {
        0%, 100% { box-shadow: 0 4px 20px var(--primary-glow); }
        50% { box-shadow: 0 4px 30px rgba(231, 76, 60, 0.5); }
    }

    .server-btn.active {
        animation: subtlePulse 3s ease-in-out infinite;
    }
</style>

