<script>
    let currentServer1Url = "";
    let currentServer2Url = "";
    let activeServer = 1;

    function filterChapter(chapterNumber, btn) {
        document.querySelectorAll('.chapter-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        document.querySelectorAll('.ep-btn').forEach(ep => {
            if(ep.getAttribute('data-chapter') == chapterNumber) {
                ep.style.display = 'block';
            } else {
                ep.style.display = 'none';
            }
        });
    }

    function loadEpisode(btn, url1, url2 = '', showAd = true) {
        if (!url1 || url1 === '') return;

        currentServer1Url = url1;
        currentServer2Url = url2;

        // تشغيل السيرفر الحالي المختار
        if (activeServer === 1 || !currentServer2Url) {
            updateFrameSource(currentServer1Url);
            switchServerButtonsStyle(1);
        } else {
            updateFrameSource(currentServer2Url);
            switchServerButtonsStyle(2);
        }

        if (showAd) {
            document.getElementById('adOverlay').style.display = 'flex';
        }

        document.querySelectorAll('.ep-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
    }

    function switchServer(serverNum) {
        activeServer = serverNum;
        switchServerButtonsStyle(serverNum);

        if (serverNum === 1 && currentServer1Url) {
            updateFrameSource(currentServer1Url);
        } else if (serverNum === 2 && currentServer2Url) {
            updateFrameSource(currentServer2Url);
        }
    }

    function switchServerButtonsStyle(serverNum) {
        document.getElementById('server1Btn').classList.remove('active');
        document.getElementById('server2Btn').classList.remove('active');
        document.getElementById('server' + serverNum + 'Btn').classList.add('active');
    }

    function updateFrameSource(url) {
        let finalUrl = url;
        if (url.includes('drive.google.com')) {
            let fileId = "";
            if (url.includes('/file/d/')) {
                fileId = url.split('/file/d/')[1].split('/')[0];
            } else if (url.includes('id=')) {
                fileId = url.split('id=')[1].split('&')[0];
            }
            finalUrl = `https://drive.google.com/file/d/${fileId}/preview`;
        }
        document.getElementById('customPlayerFrame').src = finalUrl;
    }

    function closeAd() {
        document.getElementById('adOverlay').style.display = 'none';
    }

    window.onload = function() {
        filterChapter(1, document.querySelector('.chapter-btn'));

        const firstBtn = document.querySelector('.ep-btn');
        if (firstBtn) {
            const onclickAttr = firstBtn.getAttribute('onclick');
            // استخراج الروابط بشكل صحيح لتشغيل أول حلقة تلقائياً عند الفتح
            const matches = [...onclickAttr.matchAll(/'([^']*)'/g)];
            if (matches.length > 0 && matches[0][1] !== 'رابط_1') {
                const url1 = matches[0] ? matches[0][1] : '';
                const url2 = matches[1] ? matches[1][1] : '';
                loadEpisode(firstBtn, url1, url2, false);
            }
        }
    };
</script>

