<style>
    @import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700;800;900&display=swap');

    :root {
        --primary-color: #e74c3c;
        --primary-glow: rgba(231, 76, 60, 0.35);
        --primary-dark: #c0392b;
        --bg-dark: #0a0a0f;
        --bg-card: #111118;
        --bg-elevated: #1a1a25;
        --border-subtle: rgba(255, 255, 255, 0.06);
        --border-active: rgba(231, 76, 60, 0.4);
        --text-primary: #f0f0f5;
        --text-muted: #6b6b80;
        --accent-gradient: linear-gradient(135deg, #e74c3c 0%, #ff6b6b 50%, #e74c3c 100%);
        --card-glow: 0 0 80px rgba(231, 76, 60, 0.06);
    }

    * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
    }

    .episode-container {
        display: flex;
        flex-direction: column;
        background: var(--bg-card);
        border-radius: 20px;
        overflow: hidden;
        font-family: 'Tajawal', sans-serif;
        box-shadow: var(--card-glow), 0 25px 60px rgba(0, 0, 0, 0.6);
        direction: rtl;
        max-width: 900px;
        margin: 30px auto;
        border: 1px solid var(--border-subtle);
        position: relative;
    }

    .episode-container::before {
        content: '';
        position: absolute;
        top: -1px;
        left: 20%;
        right: 20%;
        height: 2px;
        background: var(--accent-gradient);
        border-radius: 0 0 10px 10px;
        z-index: 2;
    }

    .video-wrapper {
        position: relative;
        background: radial-gradient(ellipse at center, #111118 0%, #000000 100%);
        padding: 12px;
        aspect-ratio: 16/9;
    }

    .video-wrapper::after {
        content: '';
        position: absolute;
        bottom: 0;
        left: 12px;
        right: 12px;
        height: 1px;
        background: linear-gradient(90deg, transparent, var(--primary-color), transparent);
        opacity: 0.3;
    }

    .block-popout {
        position: absolute;
        top: 12px;
        right: 12px;
        width: 60px;
        height: 60px;
        z-index: 10;
        background: rgba(255, 255, 255, 0);
        cursor: default;
    }

    #customPlayerFrame {
        width: 100%;
        height: 100%;
        border-radius: 12px;
        border: 1px solid var(--border-subtle);
        display: block;
        background: #000;
    }

    /* === قسم السيرفر === */
    .server-selection {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 15px;
        padding: 16px 20px;
        background: linear-gradient(180deg, var(--bg-elevated) 0%, var(--bg-card) 100%);
        border-bottom: 1px solid var(--border-subtle);
    }

    .server-selection span {
        color: var(--text-muted);
        font-size: 13px;
        font-weight: 500;
        letter-spacing: 0.3px;
    }

    .server-btn {
        background: var(--bg-dark);
        color: var(--text-primary);
        border: 1px solid var(--border-subtle);
        padding: 9px 24px;
        border-radius: 10px;
        cursor: pointer;
        font-size: 13px;
        font-weight: 700;
        font-family: 'Tajawal', sans-serif;
        transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
        position: relative;
        overflow: hidden;
    }

    .server-btn::before {
        content: '';
        position: absolute;
        inset: 0;
        background: var(--accent-gradient);
        opacity: 0;
        transition: opacity 0.35s;
    }

    .server-btn span {
        position: relative;
        z-index: 1;
    }

    .server-btn:hover {
        border-color: var(--border-active);
        transform: translateY(-1px);
        box-shadow: 0 4px 20px var(--primary-glow);
    }

    .server-btn.active {
        background: var(--accent-gradient);
        border-color: transparent;
        color: white;
        box-shadow: 0 4px 25px var(--primary-glow), 0 0 0 1px rgba(231, 76, 60, 0.2);
    }

    /* === أزرار الفصول === */
    .chapters-nav {
        display: flex;
        gap: 8px;
        padding: 16px 20px 0;
        background: var(--bg-card);
        flex-wrap: wrap;
    }

    .chapter-btn {
        background: var(--bg-dark);
        color: var(--text-muted);
        border: 1px solid var(--border-subtle);
        padding: 9px 18px;
        border-radius: 10px;
        cursor: pointer;
        font-size: 12.5px;
        font-weight: 600;
        font-family: 'Tajawal', sans-serif;
        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        white-space: nowrap;
    }

    .chapter-btn:hover {
        color: var(--text-primary);
        border-color: rgba(255, 255, 255, 0.12);
        background: var(--bg-elevated);
        transform: translateY(-1px);
    }

    .chapter-btn.active {
        background: var(--accent-gradient);
        color: white;
        border-color: transparent;
        box-shadow: 0 3px 18px var(--primary-glow);
    }

    /* === قائمة الحلقات === */
    .episodes-list {
        background: var(--bg-card);
        padding: 20px;
    }

    .episodes-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(82px, 1fr));
        gap: 8px;
        max-height: 260px;
        overflow-y: auto;
        padding: 4px;
    }

    .ep-btn {
        background: var(--bg-dark);
        color: var(--text-muted);
        border: 1px solid var(--border-subtle);
        padding: 10px 6px;
        border-radius: 10px;
        cursor: pointer;
        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        font-size: 13px;
        font-weight: 600;
        font-family: 'Tajawal', sans-serif;
        display: none;
        text-align: center;
        line-height: 1.4;
        position: relative;
        overflow: hidden;
    }

    .ep-btn::before {
        content: '';
        position: absolute;
        inset: 0;
        background: var(--accent-gradient);
        opacity: 0;
        transition: opacity 0.3s;
    }

    .ep-btn:hover {
        color: var(--text-primary);
        border-color: rgba(255, 255, 255, 0.1);
        transform: translateY(-2px);
        box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4);
    }

    .ep-btn.active {
        background: var(--accent-gradient);
        color: white;
        border-color: transparent;
        box-shadow: 0 4px 20px var(--primary-glow);
        transform: scale(1.04);
    }

    /* === شريط التمرير === */
    .episodes-grid::-webkit-scrollbar {
        width: 4px;
    }

    .episodes-grid::-webkit-scrollbar-track {
        background: transparent;
    }

    .episodes-grid::-webkit-scrollbar-thumb {
        background: linear-gradient(180deg, var(--primary-color), var(--primary-dark));
        border-radius: 10px;
    }

    /* === المودال الإعلاني === */
    .ad-overlay {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0, 0, 0, 0.88);
        display: none;
        justify-content: center;
        align-items: center;
        z-index: 9999;
        backdrop-filter: blur(12px);
        animation: fadeInOverlay 0.3s ease;
    }

    @keyframes fadeInOverlay {
        from { opacity: 0; }
        to { opacity: 1; }
    }

    .ad-modal {
        background: linear-gradient(160deg, #1a1a25 0%, #111118 100%);
        padding: 28px;
        border-radius: 20px;
        max-width: 400px;
        width: 90%;
        text-align: center;
        position: relative;
        border: 1px solid var(--border-subtle);
        box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6);
        animation: slideUpModal 0.4s cubic-bezier(0.16, 1, 0.3, 1);
    }

    @keyframes slideUpModal {
        from { opacity: 0; transform: translateY(30px) scale(0.95); }
        to { opacity: 1; transform: translateY(0) scale(1); }
    }

    .ad-modal h3 {
        color: var(--text-primary);
        margin-top: 0;
        font-size: 18px;
        font-weight: 800;
    }

    .ad-placeholder {
        margin-bottom: 18px;
        min-height: 200px;
        background: var(--bg-dark);
        border-radius: 12px;
        padding: 10px;
        border: 1px solid var(--border-subtle);
    }

    .close-ad-btn {
        background: var(--accent-gradient);
        color: white;
        border: none;
        padding: 13px 28px;
        border-radius: 12px;
        cursor: pointer;
        font-weight: 800;
        font-size: 14px;
        font-family: 'Tajawal', sans-serif;
        width: 100%;
        margin-top: 15px;
        transition: all 0.3s;
        letter-spacing: 0.3px;
    }

    .close-ad-btn:hover {
        transform: translateY(-2px);
        box-shadow: 0 8px 30px var(--primary-glow);
    }

    /* === زر العودة === */
    .back-btn-wrapper {
        margin: 30px 20px;
        text-align: center;
    }

    .back-btn-wrapper a {
        background: var(--accent-gradient);
        border-radius: 50px;
        color: white;
        display: inline-block;
        font-family: 'Tajawal', sans-serif;
        font-weight: 800;
        padding: 13px 32px;
        text-decoration: none;
        font-size: 14px;
        transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
        box-shadow: 0 4px 20px var(--primary-glow);
        letter-spacing: 0.3px;
    }

    .back-btn-wrapper a:hover {
        transform: translateY(-3px);
        box-shadow: 0 8px 35px rgba(231, 76, 60, 0.45);
    }

    /* === حركات عامة === */
    @keyframes subtlePulse {
        0%, 100% { box-shadow: 0 4px 20px var(--primary-glow); }
        50% { box-shadow: 0 4px 30px rgba(231, 76, 60, 0.5); }
    }

    .server-btn.active {
        animation: subtlePulse 3s ease-in-out infinite;
    }
</style>

