        --text-muted: #6b6b80;
        --accent-gradient: linear-gradient(135deg, #e74c3c 0%, #ff6b6b 50%, #e74c3c 100%);
        --card-glow: 0 0 80px rgba(231, 76, 60, 0.06);
        --plyr-color-main: var(--primary-color);
    }

    * { margin: 0; padding: 0; box-sizing: border-box; }

    .episode-container {
        display: flex;
        flex-direction: column;
        background: var(--bg-card);
        border-radius: 20px;
        overflow: hidden;
        font-family: 'Tajawal', sans-serif;
        box-shadow: var(--card-glow), 0 25px 60px rgba(0, 0, 0, 0.6);
        direction: rtl;
        max-width: 900px;
        margin: 30px auto;
        border: 1px solid var(--border-subtle);
        position: relative;
    }

    .episode-container::before {
        content: '';
        position: absolute;
        top: -1px; left: 20%; right: 20%; height: 2px;
        background: var(--accent-gradient);
        border-radius: 0 0 10px 10px; z-index: 2;
    }

    .video-wrapper {
        position: relative;
        background: #000;
        padding: 12px;
        border-radius: 20px 20px 0 0;
    }

    /* ===== زر التكبير ===== */
    .fullscreen-btn {
        position: absolute;
        top: 20px;
        left: 20px;
        z-index: 100;
        width: 40px;
        height: 40px;
        background: rgba(0, 0, 0, 0.65);
        border: 1px solid rgba(255,255,255,0.15);
        border-radius: 10px;
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        color: #fff;
        transition: background 0.25s, transform 0.2s;
        backdrop-filter: blur(6px);
    }
    .fullscreen-btn:hover {
        background: var(--primary-color);
        border-color: transparent;
        transform: scale(1.08);
    }
    .fullscreen-btn svg {
        width: 18px;
        height: 18px;
        pointer-events: none;
    }

    /* ===== وضع الشاشة الكاملة للـ wrapper ===== */
    .video-wrapper.is-fullscreen {
        position: fixed !important;
        top: 0 !important; left: 0 !important;
        width: 100vw !important; height: 100vh !important;
        padding: 0 !important;
        border-radius: 0 !important;
        z-index: 99999 !important;
        background: #000 !important;
    }
    .video-wrapper.is-fullscreen .plyr,
    .video-wrapper.is-fullscreen #externalFrame {
        width: 100% !important;
        height: 100% !important;
        border-radius: 0 !important;
        border: none !important;
    }
    .video-wrapper.is-fullscreen .cinema-bar-top {
        top: 0; left: 0; right: 0; border-radius: 0;
    }
    .video-wrapper.is-fullscreen .cinema-bar-bottom {
        bottom: 0; left: 0; right: 0; border-radius: 0;
    }
    .video-wrapper.is-fullscreen .fullscreen-btn {
        top: 14px;
        left: 14px;
    }

    .plyr__video-wrapper--youtube iframe {
        pointer-events: none !important;
    }

    .cinema-bar-top {
        position: absolute;
        top: 12px; left: 12px; right: 12px;
        height: 68px;
        background: #000;
        z-index: 30;
        pointer-events: none;
        border-radius: 12px 12px 0 0;
        opacity: 1;
        transition: none;
    }
    .cinema-bar-bottom {
        position: absolute;
        bottom: 12px; left: 12px; right: 12px;
        height: 54px;
        background: #000;
        z-index: 30;
        pointer-events: none;
        border-radius: 0 0 12px 12px;
        opacity: 1;
        transition: none;
    }
    .cinema-bar-top.hidden,
    .cinema-bar-bottom.hidden { opacity: 0; }

    .plyr {
        border-radius: 12px;
        border: 1px solid var(--border-subtle);
        overflow: hidden;
        box-shadow: 0 10px 30px rgba(0,0,0,0.5);
    }
    .plyr.plyr--hidden { display: none !important; }

    #externalFrame {
        display: none;
        width: 100%;
        aspect-ratio: 16/9;
