<script>
    const player        = new Plyr('#player', {
        youtube: { noCookie: true, rel: 0, iv_load_policy: 3, modestbranding: 1, controls: 0, disablekb: 1 }
    });

    const cinemaTop     = document.getElementById('cinemaTop');
    const cinemaBottom  = document.getElementById('cinemaBottom');
    const speedSection  = document.getElementById('speedSection');
    const externalFrame = document.getElementById('externalFrame');
    const videoWrapper  = document.getElementById('videoWrapper');
    const fsIcon        = document.getElementById('fsIcon');

    let fadeTimer    = null;
    let currentSpeed = 1;
    let isCustomFS   = false;

    // متغيرات السيرفرات
    let currentServer = 1;
    let activeEpUrls = ['', '', ''];

    const iconExpand = `
        <polyline points="15 3 21 3 21 9"></polyline>
        <polyline points="9 21 3 21 3 15"></polyline>
        <line x1="21" y1="3" x2="14" y2="10"></line>
        <line x1="3" y1="21" x2="10" y2="14"></line>`;
    const iconCollapse = `
        <polyline points="4 14 10 14 10 20"></polyline>
        <polyline points="20 4 14 4 14 10"></polyline>
        <line x1="10" y1="14" x2="3" y2="21"></line>
        <line x1="21" y1="3" x2="14" y2="10"></line>`;

    function toggleFullscreen() {
        isCustomFS = !isCustomFS;
        if (isCustomFS) {
            videoWrapper.classList.add('is-fullscreen');
            fsIcon.innerHTML = iconCollapse;
            document.body.style.overflow = 'hidden';
        } else {
            videoWrapper.classList.remove('is-fullscreen');
            fsIcon.innerHTML = iconExpand;
            document.body.style.overflow = '';
        }
    }

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && isCustomFS) toggleFullscreen();
    });

    function getPlyrEl() { return document.querySelector('.plyr'); }

    function isYoutube(url) {
        return /youtu\.be\/|youtube\.com/.test(url);
    }

    function showBars() {
        if (fadeTimer) clearTimeout(fadeTimer);
        cinemaTop.classList.remove('hidden');
        cinemaBottom.classList.remove('hidden');
        fadeTimer = setTimeout(function () {
            cinemaTop.classList.add('hidden');
            cinemaBottom.classList.add('hidden');
        }, 6000);
    }

    function hideBarsImmediately() {
        if (fadeTimer) clearTimeout(fadeTimer);
        cinemaTop.classList.add('hidden');
        cinemaBottom.classList.add('hidden');
    }

    function switchToYoutube(videoId) {
        const plyrEl = getPlyrEl();
        if (plyrEl) plyrEl.classList.remove('plyr--hidden');
        externalFrame.style.display = 'none';
        externalFrame.src = '';
        speedSection.style.display = 'flex';
        player.source = {
            type: 'video',
            sources: [{ src: videoId, provider: 'youtube' }]
        };
        showBars();
    }

    function switchToExternal(url) {
        const plyrEl = getPlyrEl();
        if (plyrEl) plyrEl.classList.add('plyr--hidden');
        externalFrame.style.display = 'block';
        externalFrame.src = url;
        speedSection.style.display = 'none';
        hideBarsImmediately();
    }

    player.on('play',   function () { showBars(); try { player.speed = currentSpeed; } catch(e){} });
    player.on('seeked', function () { showBars(); });
    player.on('ready',  function () { showBars(); });

    function setSpeed(speed, btn) {
        currentSpeed = speed;
        try { player.speed = speed; } catch(e) {}
        document.querySelectorAll('.speed-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
    }

    function filterChapter(chapterNumber, btn) {
        document.querySelectorAll('.chapter-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        document.querySelectorAll('.ep-btn').forEach(ep => {
            ep.style.display = (ep.getAttribute('data-chapter') == chapterNumber) ? 'block' : 'none';
        });
    }

    function setServer(serverNum, btn) {
        currentServer = serverNum;
        document.querySelectorAll('.server-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        // إعادة تحميل الحلقة النشطة عند تغيير السيرفر
        let activeBtn = document.querySelector('.ep-btn.active');
        if (activeBtn) {
            let urlToLoad = activeEpUrls[currentServer - 1];
            if (urlToLoad && !urlToLoad.startsWith('رابط')) {
                if (isYoutube(urlToLoad)) {
                    const ytMatch = urlToLoad.match(/(?:youtu\.be\/|youtube\.com\/(?:embed\/|v\/|watch\?v=|watch\?.+&v=))([^&?]+)/);
                    if (ytMatch) switchToYoutube(ytMatch[1]);
                } else {
                    switchToExternal(urlToLoad);
                }
            }
        }
    }

    function loadEpisode(btn, url1, url2 = '', url3 = '', showAd = true) {
        // التحقق في حال استدعاء الدالة بقيمة بوليانية كمتغير ثاني أو ثالث (للتوافقية)
        if (typeof url2 === 'boolean') { showAd = url2; url2 = ''; url3 = ''; } 
        else if (typeof url3 === 'boolean') { showAd = url3; url3 = ''; }

        activeEpUrls = [url1 || '', url2 || '', url3 || ''];
        let urlToLoad = activeEpUrls[currentServer - 1];

        if (!urlToLoad || urlToLoad.startsWith('رابط')) return;

        if (isYoutube(urlToLoad)) {
            const ytMatch = urlToLoad.match(/(?:youtu\.be\/|youtube\.com\/(?:embed\/|v\/|watch\?v=|watch\?.+&v=))([^&?]+)/);
            if (ytMatch) switchToYoutube(ytMatch[1]);
        } else {
            switchToExternal(urlToLoad);
        }

        if (showAd) document.getElementById('adOverlay').style.display = 'flex';
        document.querySelectorAll('.ep-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
    }

    function closeAd() {
        document.getElementById('adOverlay').style.display = 'none';
    }

    window.onload = function () {
        filterChapter(1, document.querySelector('.chapter-btn'));
        const firstBtn = document.querySelector('.ep-btn');
        if (firstBtn) {
            const matches = [...firstBtn.getAttribute('onclick').matchAll(/'([^']*)'/g)];
            if (matches.length >= 1) {
                const u1 = matches[0] ? matches[0][1] : '';
                const u2 = matches[1] ? matches[1][1] : '';
                const u3 = matches[2] ? matches[2][1] : '';
                if (u1 && !u1.startsWith('رابط')) {
                    loadEpisode(firstBtn, u1, u2, u3, false);
                }
            }
        }
    };
</script>

