<script>
    let currentServer = 3;
    let activeEpisodeBtn = null;

    const iframePlayer = document.getElementById('customPlayerFrame');

    function filterChapter(chapterNumber, btn) {
        document.querySelectorAll('.chapter-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        document.querySelectorAll('.ep-btn').forEach(ep => {
            if(ep.getAttribute('data-chapter') == chapterNumber) {
                ep.style.display = 'block';
            } else {
                ep.style.display = 'none';
            }
        });
    }

    function switchServer(serverId, btn) {
        document.querySelectorAll('.server-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        currentServer = serverId;

        if (activeEpisodeBtn) {
            loadEpisode(activeEpisodeBtn, false);
        }
    }

    function loadEpisode(btn, showAd = true) {
        activeEpisodeBtn = btn;

        if (showAd) {
            document.getElementById('adOverlay').style.display = 'flex';
        }

        document.querySelectorAll('.ep-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        if (currentServer === 2) {
            let okUrl = btn.getAttribute('data-ok');
            playIframe(okUrl);
        } else if (currentServer === 3) {
            let server3Url = btn.getAttribute('data-server3');
            playIframe(server3Url);
        } else if (currentServer === 4) {
            let server4Url = btn.getAttribute('data-server4');
            playIframe(server4Url);
    } else if (currentServer === 5) {
    let server5Url = btn.getAttribute('data-server5');
    playIframe(server5Url);
} else if (currentServer === 6) {
    let server6Url = btn.getAttribute('data-server6');
    playIframe(server6Url);

        }
    }

    function playIframe(url) {
        if (!url) {
            iframePlayer.src = '';
            return;
        }

        let finalUrl = url;
        if (url.includes('drive.google.com')) {
            let fileId = "";
            if (url.includes('/file/d/')) {
                fileId = url.split('/file/d/')[1].split('/')[0];
            } else if (url.includes('id=')) {
                fileId = url.split('id=')[1].split('&')[0];
            }
            finalUrl = `https://drive.google.com/file/d/${fileId}/preview`;
        }
        iframePlayer.src = finalUrl;
    }

    function closeAd() {
        document.getElementById('adOverlay').style.display = 'none';
    }

    function downloadCurrentEpisode() {
        if (!activeEpisodeBtn) {
            alert("الرجاء اختيار محاضرة أولاً.");
            return;
        }

        let server3Url = activeEpisodeBtn.getAttribute('data-server3');

        if (server3Url && server3Url.trim() !== "") {
            let downloadUrl = server3Url.replace('/e/', '/d/');
            window.open(downloadUrl, '_blank');
        } else {
            alert("عذراً، رابط التحميل غير متوفر لهذه المحاضرة.");
        }
    }

    window.onload = function() {
        filterChapter(1, document.querySelector('.chapter-btn'));

        const firstBtn = document.querySelector('.ep-btn');
        if (firstBtn) {
            loadEpisode(firstBtn, false);
        }
    };
</script>

