<style>
.wchPg{--void:#06060b;--void-light:#0b0b14;--void-card:#0e0e1a;--void-up:#161624;--gold:#d4af37;--gold-b:#f2d486;--gold-dim:#9a7b2e;--text:#e2dcd0;--text-dim:#9a958c;--border:rgba(200,162,78,.08);--border-g:rgba(200,162,78,.18);--font-d:'Aref Ruqaa',serif;--font-b:'Almarai',sans-serif;
  display:block;position:relative;z-index:1;overflow:hidden;background:var(--void);color:var(--text);font-family:var(--font-b);line-height:1.8;direction:rtl;text-align:right;border-radius:22px;width:100%;box-sizing:border-box}
.wchPg *{box-sizing:border-box;margin:0;padding:0}
.wchPg a{text-decoration:none;color:inherit}
.wchPg img{display:block;max-width:100%}
.wchPg svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-linecap:round;stroke-linejoin:round;stroke-width:1.6;flex-shrink:0}
.wchPg button{font-family:inherit;cursor:pointer;border:none;background:none;color:inherit}
.wch-inner{max-width:1060px;margin:0 auto;padding:34px 20px 56px;position:relative;z-index:2}
.wch-top{position:absolute;top:-140px;left:50%;transform:translateX(-50%);width:640px;height:380px;background:radial-gradient(closest-side,rgba(212,175,55,.14),transparent);pointer-events:none;z-index:-1}
.wch-orn{position:absolute;top:-60px;right:-70px;width:230px;height:230px;border:1px dashed var(--border-g);border-radius:50%;opacity:.5;pointer-events:none}
.wch-orn2{position:absolute;bottom:-90px;left:-70px;width:280px;height:280px;border:1px dashed var(--border-g);border-radius:50%;opacity:.4;pointer-events:none}

/* شريط علوي */
.wch-navbar{display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid var(--border);padding-bottom:16px}
.wch-brand{display:inline-flex;align-items:center;gap:9px;font-family:var(--font-d);font-weight:700;font-size:17px;color:var(--gold-b)}
.wch-brand svg{color:var(--gold)}
.wch-badge{display:inline-flex;align-items:center;gap:7px;padding:7px 16px;border-radius:40px;border:1px solid var(--border-g);background:rgba(212,175,55,.06);color:var(--gold-b);font-size:12.5px}
.wch-badge::before{content:'';width:7px;height:7px;border-radius:50%;background:var(--gold);box-shadow:0 0 10px var(--gold);animation:wch-pulse 2s infinite}
@keyframes wch-pulse{0%,100%{opacity:1}50%{opacity:.4}}

/* عنوان المسلسل والحلقة */
.wch-head{padding:26px 0 6px}
.wch-title{font-family:var(--font-d);font-weight:700;font-size:clamp(22px,3.4vw,32px);color:#f6efdf}
.wch-crumb{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:8px;color:var(--text-dim);font-size:13.5px}
.wch-crumb b{color:var(--gold-b);font-weight:700}

/* مشغل الفيديو */
.wch-player{position:relative;margin-top:20px;border-radius:20px;overflow:hidden;border:1px solid var(--border-g);background:var(--void-card);box-shadow:0 24px 60px -28px rgba(0,0,0,.75)}
.wch-player .frame-box{position:relative;width:100%;aspect-ratio:16/9;background:#000}
.wch-player iframe{position:absolute;inset:0;width:100%;height:100%;border:0}
.wch-player .empty{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;color:var(--text-dim);font-size:14px;text-align:center;padding:20px}
.wch-player .empty .ic{width:52px;height:52px;border-radius:50%;background:rgba(212,175,55,.08);display:flex;align-items:center;justify-content:center;color:var(--gold)}

/* السيرفرات */
.wch-servers{margin-top:18px}
.wch-servers .lbl{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text-dim)}
.wch-servers .lbl svg{width:16px;height:16px;color:var(--gold-dim)}
.wch-srv-row{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}
.wch-srv{display:inline-flex;align-items:center;gap:8px;padding:10px 18px;border-radius:40px;border:1px solid var(--border-g);background:linear-gradient(160deg,var(--void-card),var(--void-light));color:var(--text-dim);font-size:13.5px;font-weight:700;transition:border-color .25s,color .25s,background .25s,transform .2s}
.wch-srv:hover{transform:translateY(-2px);border-color:rgba(212,175,55,.4);color:var(--gold-b)}
.wch-srv .dot{width:7px;height:7px;border-radius:50%;background:var(--text-dim);transition:background .25s,box-shadow .25s}
.wch-srv.active{color:#0b0b14;background:linear-gradient(135deg,#d4af37,#a9822a);border-color:transparent;box-shadow:0 10px 26px -12px rgba(212,175,55,.6)}
.wch-srv.active .dot{background:#0b0b14;box-shadow:none}

/* شريط التنقل بين الحلقات */
.wch-nav{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:26px;padding:14px 18px;border-radius:16px;background:linear-gradient(160deg,var(--void-card),var(--void-light));border:1px solid var(--border)}
.wch-navbtn{display:inline-flex;align-items:center;gap:7px;padding:9px 16px;border-radius:12px;font-size:13.5px;font-weight:700;color:var(--gold-b);border:1px solid var(--border-g);background:rgba(212,175,55,.05);transition:.25s}
.wch-navbtn:hover{background:rgba(212,175,55,.12)}
.wch-navbtn[disabled]{opacity:.35;pointer-events:none}
.wch-counter{text-align:center;font-family:var(--font-d);font-weight:700;font-size:16px;color:#f6efdf}
.wch-counter span{display:block;font-family:var(--font-b);font-weight:400;font-size:11.5px;color:var(--text-dim);margin-top:2px}

/* شبكة الحلقات */
.wch-sec{margin-top:38px}
.wch-sec .sh{display:flex;align-items:center;justify-content:space-between;gap:10px}
.wch-sec h2{font-family:var(--font-d);font-weight:700;font-size:clamp(19px,2.6vw,24px);color:#f6efdf}
.wch-eplist{display:grid;grid-template-columns:repeat(auto-fill,minmax(64px,1fr));gap:10px;margin-top:18px;max-height:260px;overflow-y:auto;padding-left:4px}
.wch-eplist::-webkit-scrollbar{width:6px}
.wch-eplist::-webkit-scrollbar-thumb{background:var(--border-g);border-radius:10px}
.wch-ep{display:flex;align-items:center;justify-content:center;padding:12px 0;border-radius:12px;border:1px solid var(--border-g);background:linear-gradient(160deg,var(--void-card),var(--void-light));font-weight:700;font-size:14px;color:var(--text-dim);transition:transform .2s,border-color .2s,color .2s,background .2s}
.wch-ep:hover{transform:translateY(-2px);border-color:rgba(212,175,55,.4);color:var(--gold-b)}
.wch-ep.active{color:#0b0b14;background:linear-gradient(135deg,#d4af37,#a9822a);border-color:transparent;box-shadow:0 10px 24px -12px rgba(212,175,55,.55)}

/* إعلان */
.wch-ad{display:flex;align-items:center;justify-content:center;gap:12px;width:100%;height:90px;margin:30px auto 0;border-radius:16px;border:1px dashed var(--border-g);background:linear-gradient(160deg,var(--void-card),var(--void-light));color:var(--gold-b);font-family:var(--font-d);font-weight:700;font-size:clamp(18px,3vw,22px);text-align:center;transition:border-color .3s,background .3s,box-shadow .3s}
.wch-ad:hover{border-color:var(--gold);background:rgba(212,175,55,.1);box-shadow:0 14px 34px -18px rgba(212,175,55,.45)}
.wch-ad .ad-label{font-family:var(--font-b);font-size:11px;padding:3px 10px;border-radius:6px;border:1px solid var(--border-g);color:var(--text-dim);flex-shrink:0}

/* رجوع للرئيسية */
.wch-home{display:flex;flex-direction:column;align-items:center;gap:12px;margin-top:36px}
.wch-btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;padding:12px 26px;border-radius:44px;font-weight:700;font-size:15px;transition:.3s;width:100%;max-width:320px}
.wch-btn.gh{color:var(--gold-b);border:1px solid var(--border-g);background:rgba(212,175,55,.06)}
.wch-btn.gh:hover{background:rgba(212,175,55,.12);transform:translateY(-2px)}
.wch-btn.tg{color:#0b0b14;border:1px solid transparent;background:linear-gradient(135deg,#3fb0e6,#1287c9)}
.wch-btn.tg:hover{transform:translateY(-2px);box-shadow:0 14px 30px -14px rgba(40,150,220,.55)}
.wch-foot{margin-top:34px;text-align:center;color:var(--text-dim);font-size:12.5px;opacity:.7}

@media (max-width:700px){
  .wch-inner{padding:26px 14px 44px}
  .wch-nav{flex-wrap:nowrap}
  .wch-navbtn span{display:none}
  .wch-ad{height:76px}
