      frame.classList.remove('hidden');
      empty.classList.add('hidden');
    }else{
      frame.src = "";
      frame.classList.add('hidden');
      empty.classList.remove('hidden');
    }
  }

  function renderServers(){
    var ep = currentEpisode();
    srvRow.innerHTML='';
    ep.servers.forEach(function(srv, i){
      var b=document.createElement('button');
      b.type='button';
      b.className='wch-srv'+(i===srvIndex?' active':'');
      b.innerHTML='<span class="dot"></span>'+srv.name;
      b.addEventListener('click', function(){
        srvIndex=i;
        renderServers();
        renderPlayer();
      });
      srvRow.appendChild(b);
    });
  }

  function renderNav(){
    var total=SERIES.episodes.length;
    counterMain.textContent = 'الحلقة '+currentEpisode().num+' من '+total;
    crumbEp.textContent = 'الحلقة '+currentEpisode().num;
    prevBtn.disabled = epIndex<=0;
    nextBtn.disabled = epIndex>=total-1;
  }

  function renderEpList(){
    epList.innerHTML='';
    SERIES.episodes.forEach(function(ep, i){
      var b=document.createElement('button');
      b.type='button';
      b.className='wch-ep'+(i===epIndex?' active':'');
      b.textContent=ep.num;
      b.addEventListener('click', function(){
        goTo(i);
      });
      epList.appendChild(b);
    });
  }

  function goTo(i){
    if(i<0 || i>=SERIES.episodes.length) return;
    epIndex=i;
    srvIndex=0;
    renderServers();
    renderPlayer();
    renderNav();
    renderEpList();
    var top = document.getElementById('watchPage');
    if(top && top.scrollIntoView) top.scrollIntoView({behavior:'smooth', block:'start'});
  }

  prevBtn.addEventListener('click', function(){ goTo(epIndex-1); });
  nextBtn.addEventListener('click', function(){ goTo(epIndex+1); });

  renderServers();
  renderPlayer();
  renderNav();
  renderEpList();
})();
</script>
