  function renderEpList(){
    epList.innerHTML='';
    SERIES.episodes.forEach(function(ep, i){
      var b=document.createElement('button');
      b.type='button';
      b.className='wch-ep'+(i===epIndex?' active':'');
      b.textContent=ep.num;
      b.addEventListener('click', function(){
        goTo(i);
      });
      epList.appendChild(b);
    });
  }

  function goTo(i){
    if(i<0 || i>=SERIES.episodes.length) return;
